<?php
namespace App\Services;
use App\Models\EpidemiologyModel;
final class EpidemiologyService {
 public function analyse(): array {$m=new EpidemiologyModel();$rows=$m->districtMedicationTotals();$trends=[];foreach($m->monthlyDistrictTotals() as $r)$trends[$r['District']][$r['Mois']]=(int)$r['Total'];$weights=['Antipyrétique'=>3,'Antidiarrhéique'=>2.8,'Antibiotique'=>2,'Antalgique'=>1.2,'VitamineC'=>.5,'Antihistaminique'=>1.5];$groups=[];foreach($rows as $r)$groups[$r['District']][]=$r;$risks=[];$alerts=[];foreach($groups as $district=>$items){$base=0;$total=0;foreach($items as $i){$base+=(int)$i['Total']*($weights[$i['Type']]??1);$total+=(int)$i['Total'];}$bonus=count($items)>=3?1.3:(count($items)>=2?1.15:1);$values=array_values($trends[$district]??[]);$trend=1;if(count($values)>=2){$last=$values[count($values)-1];$previous=$values[count($values)-2];if($previous>0&&$last>$previous*1.5)$trend=1.5;elseif($previous>0&&$last>$previous*1.2)$trend=1.25;}$score=$base*$bonus*$trend;$level=$score>=200?5:($score>=100?4:($score>=50?3:($score>=20?2:1)));$risks[$district]=$level;if($level>=3){usort($items,fn($a,$b)=>(int)$b['Total']<=>(int)$a['Total']);$alerts[]=['district'=>$district,'niveau'=>$level,'score'=>round($score,1),'total'=>$total,'type_dominant'=>$items[0]['Type'],'tendance'=>$trend>1?'En hausse':'Stable'];}}usort($alerts,fn($a,$b)=>$b['niveau']<=>$a['niveau']);return compact('rows','trends','risks','alerts');}
}
